//! Third-party notices shown in the About screen (and shipped with the installers): every
//! bundled component with its version, licence and where to get its exact source, plus the
//! generated list of Rust crates compiled into videolore.

use crate::ffmpeg::FfmpegInfo;
use crate::packaging;

/// Hand-written notices (components, written offer, patent note).
pub const THIRD_PARTY: &str = include_str!("../packaging/notices/third-party.txt");
/// Rust crates and their licence texts, generated by `scripts/notices.sh` (cargo-about).
pub const RUST_CRATES: &str = include_str!("../packaging/notices/rust-crates.txt");

/// One bundled or downloadable component.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Component {
    pub name: &'static str,
    pub version: String,
    pub licence: &'static str,
    pub source: &'static str,
}

/// Every component the installers contain or download on request. The ffmpeg version is
/// the one actually running when known, otherwise the pinned build of this platform.
pub fn components(ffmpeg: Option<&FfmpegInfo>) -> Vec<Component> {
    let pinned = packaging::ffmpeg_pin(packaging::current_target())
        .and_then(|e| e.get("version").map(str::to_string))
        .unwrap_or_else(|| "unknown".into());
    let ffmpeg_version = match ffmpeg {
        Some(i) => format!("{} ({}; pinned build {pinned})", i.version, i.source),
        None => format!("{pinned} (pinned build)"),
    };
    let c = |name, version: &str, licence, source| Component {
        name,
        version: version.to_string(),
        licence,
        source,
    };
    vec![
        Component {
            name: "FFmpeg",
            version: ffmpeg_version,
            licence: "GPL-3.0-or-later",
            source: "https://ffmpeg.org/download.html",
        },
        c(
            "x264",
            "as pinned by the build scripts",
            "GPL-2.0-or-later",
            "https://code.videolan.org/videolan/x264",
        ),
        c(
            "x265",
            "as pinned by the build scripts",
            "GPL-2.0-or-later",
            "https://bitbucket.org/multicoreware/x265_git",
        ),
        c(
            "libass",
            "as pinned by the build scripts",
            "ISC",
            "https://github.com/libass/libass",
        ),
        c(
            "Noto Sans Bold",
            "2.015",
            "OFL-1.1",
            "https://github.com/notofonts/latin-greek-cyrillic",
        ),
        c(
            "Noto Sans Arabic Bold",
            "2.0.4 (hinted, 2022)",
            "OFL-1.1",
            "https://github.com/notofonts/arabic",
        ),
        c(
            "Noto Sans Devanagari Bold",
            "2.0.4 (hinted, 2022)",
            "OFL-1.1",
            "https://github.com/notofonts/devanagari",
        ),
        c(
            "Phosphor Icons",
            "2.1.2 (Regular)",
            "MIT",
            "https://github.com/phosphor-icons/web",
        ),
        c(
            "whisper.cpp",
            "as bundled by whisper-rs-sys 0.15.0",
            "MIT",
            "https://github.com/ggml-org/whisper.cpp",
        ),
        c(
            "ggml-tiny-q5_1.bin",
            "pinned by SHA-256",
            "MIT",
            "https://huggingface.co/ggerganov/whisper.cpp",
        ),
        c(
            "ggml-small-q5_1.bin",
            "pinned by SHA-256",
            "MIT",
            "https://huggingface.co/ggerganov/whisper.cpp",
        ),
        c(
            "ggml-large-v3-turbo-q5_0.bin",
            "pinned by SHA-256",
            "MIT",
            "https://huggingface.co/ggerganov/whisper.cpp",
        ),
    ]
}

/// The notices of videolore player: the same without the speech engine and its models.
pub const THIRD_PARTY_PLAYER: &str = include_str!("../packaging/notices/third-party-player.txt");

/// Components of the editor that videolore player does not contain.
const EDITOR_ONLY: [&str; 4] = [
    "whisper.cpp",
    "ggml-tiny-q5_1.bin",
    "ggml-small-q5_1.bin",
    "ggml-large-v3-turbo-q5_0.bin",
];

/// The components of videolore player (REQ-255): the editor's without the speech engine.
pub fn components_player(ffmpeg: Option<&FfmpegInfo>) -> Vec<Component> {
    let mut all = components(ffmpeg);
    all.retain(|c| !EDITOR_ONLY.contains(&c.name));
    all
}

/// Rust crates of videolore player (no speech engine, no network), generated by
/// `scripts/notices.sh`.
pub const RUST_CRATES_PLAYER: &str = include_str!("../packaging/notices/rust-crates-player.txt");

/// The full text of the About screen: a summary table, the notices and the crate list.
pub fn about_text(ffmpeg: Option<&FfmpegInfo>) -> String {
    about_text_for("videolore", components(ffmpeg), THIRD_PARTY, RUST_CRATES)
}

/// The About text of videolore player: the same components, its own crate list.
pub fn about_text_player(ffmpeg: Option<&FfmpegInfo>) -> String {
    about_text_for(
        "videolore player",
        components_player(ffmpeg),
        THIRD_PARTY_PLAYER,
        RUST_CRATES_PLAYER,
    )
}

fn about_text_for(name: &str, list: Vec<Component>, third_party: &str, crates: &str) -> String {
    let mut out = format!(
        "{name} {} — GPL-3.0-only — Copyright (C) Andrea Lorenzani\n\nBundled components\n",
        env!("CARGO_PKG_VERSION")
    );
    for c in list {
        out.push_str(&format!(
            "  {}  {}  [{}]  {}\n",
            c.name, c.version, c.licence, c.source
        ));
    }
    out.push('\n');
    out.push_str(third_party);
    out.push('\n');
    out.push_str(crates);
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ffmpeg::{BinSource, FfVersion};

    // covers: REQ-143
    #[test]
    fn the_icon_set_is_listed_with_its_licence_text_and_source() {
        let c = components(None);
        let icons = c.iter().find(|c| c.name == "Phosphor Icons").unwrap();
        assert_eq!(
            (icons.licence, icons.version.as_str()),
            ("MIT", "2.1.2 (Regular)")
        );
        assert!(icons.source.contains("phosphor-icons"));
        let about = about_text(None);
        assert!(about.contains("Phosphor Icons"));
        // the full MIT text of the set is in the notices, and the font file's own notice
        let licence = include_str!("../assets/icons/LICENSE-Phosphor.txt");
        for line in licence.lines().filter(|l| l.trim().len() > 20) {
            assert!(THIRD_PARTY.contains(line.trim()), "{line}");
        }
        // the version in the notices is the font's (recorded in SOURCE.txt)
        assert!(include_str!("../assets/icons/SOURCE.txt").contains("2.1.2"));
    }

    // covers: REQ-031
    #[test]
    fn the_splash_images_are_own_work_licensed_mit() {
        let at = THIRD_PARTY
            .find("assets/splash/splash.gif")
            .expect("splash images listed");
        let entry = &THIRD_PARTY[at..at + 400.min(THIRD_PARTY.len() - at)];
        assert!(entry.contains("splash-player.gif"));
        assert!(entry.contains("Own work of Andrea Lorenzani, licensed MIT."));
        assert!(!THIRD_PARTY.contains("to be confirmed"));
        // both programs show these notices
        assert!(about_text(None).contains("Own work of Andrea Lorenzani"));
        assert!(about_text_player(None).contains("Own work of Andrea Lorenzani"));
    }

    // covers: REQ-031
    #[test]
    fn every_component_has_version_licence_and_source() {
        let info = FfmpegInfo {
            ffmpeg: "ffmpeg".into(),
            ffprobe: "ffprobe".into(),
            version: FfVersion::Release(9, 0, 2),
            filters: Default::default(),
            encoders: Default::default(),
            source: BinSource::Bundled,
        };
        let list = components(Some(&info));
        assert!(list[0].version.contains("9.0"));
        assert!(list[0].version.contains("included with videolore"));
        let names: Vec<&str> = list.iter().map(|c| c.name).collect();
        for n in [
            "FFmpeg",
            "x264",
            "x265",
            "libass",
            "Noto Sans Bold",
            "Noto Sans Arabic Bold",
            "Noto Sans Devanagari Bold",
            "whisper.cpp",
            "Phosphor Icons",
        ] {
            assert!(names.contains(&n), "{n} missing");
        }
        // every speech file offered by Subtitle quality is listed
        for m in crate::stt::builtin_models() {
            assert!(names.contains(&m.file.as_str()), "{} missing", m.file);
        }
        for c in &list {
            assert!(!c.version.is_empty() && c.source.starts_with("https://"));
            // the shipped notices name every component with its licence
            assert!(THIRD_PARTY.contains(c.name), "{} not in notices", c.name);
            let lic = c.licence.split('-').next().unwrap();
            assert!(
                THIRD_PARTY.contains(lic),
                "{} licence not in notices",
                c.name
            );
        }
        // without a running ffmpeg the pinned build is shown
        assert!(components(None)[0].version.contains("pinned"));
        // written offer, patent note and the Rust crate licences are included
        let text = about_text(Some(&info));
        assert!(text.contains("Written offer"));
        assert!(text.contains("Patents"));
        assert!(text.contains("eframe") && text.contains("serde"));
        assert!(text.contains("GPL-3.0-only"));
        // the player lists its own crates: no speech engine, no network code
        let player = about_text_player(Some(&info));
        assert!(player.starts_with("videolore player "));
        assert!(player.contains("eframe") && !player.contains("ureq"));
        assert!(text.starts_with("videolore "));
    }

    // covers: REQ-255
    #[test]
    fn the_player_about_names_its_own_components_from_its_own_notice_file() {
        let text = about_text_player(None);
        for gone in EDITOR_ONLY {
            assert!(!text.contains(gone), "{gone} in the player's About");
        }
        assert!(!text.to_lowercase().contains("whisper"));
        for kept in ["FFmpeg", "libass", "Noto Sans Bold", "Phosphor Icons"] {
            assert!(text.contains(kept), "{kept}");
        }
        // the editor's notice file is the player's plus the speech engine and its models
        let editor = about_text(None);
        assert!(editor.contains("whisper.cpp") && editor.contains("ggml-tiny-q5_1.bin"));
        assert!(text.contains("rust-crates-player.txt") && !text.contains("\"rust-crates.txt\""));
        // the player's file is the editor's without the whisper block
        let start = THIRD_PARTY.find("whisper.cpp (speech").unwrap();
        assert!(THIRD_PARTY_PLAYER.starts_with(&THIRD_PARTY[..start]));
        let tail = THIRD_PARTY.find("Source code\n").unwrap();
        assert!(THIRD_PARTY_PLAYER.ends_with(&THIRD_PARTY[tail..]));
    }
}
